import json
events_by_role = {}
events_by_type = {}
with open('/home/ubuntu/.agent-ml-research-idea_gen_0514_1/projects/struct_self_consist_ie/logs/ralph_loop_timeline.jsonl') as f:
    for line in f:
        try:
            obj = json.loads(line)
        except:
            continue
        role = obj.get('role', '?')
        ev = obj.get('event', '?')
        events_by_role.setdefault(role, []).append(obj)
        events_by_type.setdefault(ev, 0)
        events_by_type[ev] += 1

print('Event types:')
for k, v in sorted(events_by_type.items(), key=lambda x: -x[1]):
    print(f'  {k}: {v}')

# Find escalations
escalations = []
for role, evs in events_by_role.items():
    for e in evs:
        if 'ESCALATE' in e.get('event', ''):
            escalations.append((e.get('timestamp', ''), role, e.get('event', ''), e.get('detail', '')[:200] if isinstance(e.get('detail'), str) else str(e.get('detail', ''))[:200]))

escalations.sort()
print(f'\n=== ESCALATIONS: {len(escalations)} ===')
for ts, role, ev, det in escalations[:30]:
    print(f'{ts} {role} {ev} | {det[:150]}')
EOF
